edits.before:
self._onKeyChange = function(e)
{
    e = e || window.event;

    if (self.isVisible()) {

        switch(e.keyCode){
            case 13:
            case 27:
                if (opts.field) {
                    opts.field.blur();
                }
                break;
            case 37:
                self.adjustDate('subtract', 1);
                break;
            case 38:
                self.adjustDate('subtract', 7);
                break;
            case 39:
                self.adjustDate('add', 1);
                break;
            case 40:
                self.adjustDate('add', 7);
                break;
            case 8:
            case 46:
                self.setDate(null);
                break;
        }
    }
};

edits.after:
self._onKeyChange = function(e)
{
    e = e || window.event;

    if (self.isVisible()) {

        function isDisabled(date) {
            if (opts.minDate && date < opts.minDate) return true;
            if (opts.maxDate && date > opts.maxDate) return true;
            if (opts.disableWeekends) {
                var day = date.getDay();
                if (day === 0 || day === 6) return true;
            }
            if (opts.disableDayFn && opts.disableDayFn(date)) return true;
            return false;
        }

        function shiftDate(amount) {
            var current = self.getDate() || new Date();
            if (!current) return;
            var step = amount > 0 ? 1 : -1;
            var days = Math.abs(amount);
            var candidate = new Date(current.getTime() + step * days * 24*60*60*1000);
            var min = opts.minDate;
            var max = opts.maxDate;
            while (
                candidate &&
                ((min && candidate < min) || (max && candidate > max) ? false : true) &&
                isDisabled(candidate)
            ) {
                candidate = new Date(candidate.getTime() + step * 24*60*60*1000);
            }
            if ((min && candidate < min) || (max && candidate > max)) {
                return; // out of bounds
            }
            if (!isDisabled(candidate)) {
                self.setDate(candidate);
            }
        }

        switch(e.keyCode){
            case 13:
            case 27:
                if (opts.field) {
                    opts.field.blur();
                }
                break;
            case 37:
                shiftDate(-1);
                break;
            case 38:
                shiftDate(-7);
                break;
            case 39:
                shiftDate(1);
                break;
            case 40:
                shiftDate(7);
                break;
            case 8:
            case 46:
                self.setDate(null);
                break;
        }
    }
};
